create index if not exists queuehub_events_actor_user_idx on public.queuehub_queue_events(actor_user_id);
create index if not exists queuehub_events_queue_session_idx on public.queuehub_queue_events(queue_session_id);
create index if not exists queuehub_status_queue_session_idx on public.queuehub_queue_status(queue_session_id);
drop policy if exists queuehub_staff_read_self on public.queuehub_staff_members;create policy queuehub_staff_read_self on public.queuehub_staff_members for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists queuehub_staff_read_events on public.queuehub_queue_events;create policy queuehub_staff_read_events on public.queuehub_queue_events for select to authenticated using(exists(select 1 from public.queuehub_restaurants r join public.queuehub_staff_members m on m.venue_id=r.venue_id where r.id=restaurant_id and m.user_id=(select auth.uid()) and m.is_active));
drop policy if exists queuehub_manager_read_integrations on public.queuehub_integration_configs;create policy queuehub_manager_read_integrations on public.queuehub_integration_configs for select to authenticated using(exists(select 1 from public.queuehub_restaurants r join public.queuehub_staff_members m on m.venue_id=r.venue_id where r.id=restaurant_id and m.user_id=(select auth.uid()) and m.is_active and m.role in('manager','admin')));
drop policy if exists queuehub_staff_read_sessions on public.queuehub_queue_sessions;create policy queuehub_staff_read_sessions on public.queuehub_queue_sessions for select to authenticated using(exists(select 1 from public.queuehub_restaurants r join public.queuehub_staff_members m on m.venue_id=r.venue_id where r.id=restaurant_id and m.user_id=(select auth.uid()) and m.is_active));
